package net.officefloor.hq.app.grade;

import java.util.List;
import java.util.Set;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheet's grades (A, B and C) and which of them are retired. */
@Repository
public class GradeRepository {

    /** Every grade, in order. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    private final JdbcTemplate jdbc;

    public GradeRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's retired grades. */
    public Set<String> retired(String sheetId) {
        return Set.copyOf(jdbc.queryForList("SELECT grade FROM sheet_retired_grade WHERE sheet_id = ?", String.class,
                sheetId));
    }

    public boolean isRetired(String sheetId, String grade) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM sheet_retired_grade WHERE sheet_id = ? AND grade = ?",
                Integer.class, sheetId, grade);
        return n != null && n > 0;
    }

    public void retire(String sheetId, String grade, String by) {
        jdbc.update("INSERT INTO sheet_retired_grade (sheet_id, grade, retired_by) VALUES (?, ?, ?)", sheetId, grade,
                by);
    }

    /** Refuse a grade chosen for a person (added, edited or imported) when it is retired on the sheet. */
    public void refuseRetired(String sheetId, String grade) throws RetiredGradeException {
        if (grade != null && isRetired(sheetId, grade)) {
            throw new RetiredGradeException(grade);
        }
    }
}
package net.officefloor.hq.app.grade;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user and a grade of A, B or C. */
public class ValidateGradeRetire {
    public void validate(@RequestBody GradeRetireRequest request, Out<GradeRetireRequest> body)
            throws InvalidGradeException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidGradeException("Sign in before retiring a grade.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GradeRepository.GRADES.contains(grade)) {
            throw new InvalidGradeException("The grade must be A, B or C.");
        }
        body.set(new GradeRetireRequest(request.user().trim(), grade));
    }
}
package net.officefloor.hq.app.grade;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Retire the grade on the sheet, refusing one already retired. */
public class SaveGradeRetire {
    public void save(@PathVariable("sheetId") String sheetId, @Val GradeRetireRequest request, PeriodRepository periods,
            GradeRepository grades) throws InvalidGradeException {
        String id = sheetId.trim();
        periods.lockSheet(id);
        if (grades.isRetired(id, request.grade())) {
            throw new InvalidGradeException("The grade " + request.grade() + " is already retired.");
        }
        grades.retire(id, request.grade(), request.user());
    }
}
