import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Record the retired grade in the audit file. */
public class AuditGradeRetired {
    public void audit(@PathVariable("sheetId") String sheetId, @Val GradeRetireRequest request, Audit audit) {
        audit.record("GRADE_RETIRED sheet=" + sheetId.trim() + " by=" + request.user() + " grade=" + request.grade());
    }
}
package net.officefloor.hq.app.grade;

import java.util.List;
import java.util.Set;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The grades in order, each with whether it is retired on the sheet. */
public class RespondWithGrades {
    public void respond(@PathVariable("sheetId") String sheetId, GradeRepository grades,
            ObjectResponse<List<GradeResponse>> response) {
        Set<String> retired = grades.retired(sheetId.trim());
        response.send(GradeRepository.GRADES.stream().map(g -> new GradeResponse(g, retired.contains(g))).toList());
    }
}
