package net.officefloor.hq.app.grade;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user and two different grades of
 *  A, B or C. */
public class ValidateGradeMerge {
    public void validate(@RequestBody GradeMergeRequest request, Out<GradeMergeRequest> body)
            throws InvalidGradeException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidGradeException("Sign in before merging a grade.");
        }
        String from = request.from() == null ? "" : request.from().trim();
        String into = request.into() == null ? "" : request.into().trim();
        if (!GradeRepository.GRADES.contains(from) || !GradeRepository.GRADES.contains(into)) {
            throw new InvalidGradeException("The grades must be A, B or C.");
        }
        if (from.equals(into)) {
            throw new InvalidGradeException("Choose two different grades to merge.");
        }
        body.set(new GradeMergeRequest(request.user().trim(), from, into));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.hq.app.Audit;

/** The rate form's rules and its RATE_SET line, shared by the form's set and the rate import: the grade is one of A, B
 *  or C, the rate a percent 0.00 or more with up to two decimals, the from-date and to-date (each optional) real
 *  yyyy-mm-dd dates, the to-date not before the from-date. */
public final class RateRules {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private RateRules() {
    }

    /** The rate set for the grade checked by the rate form's rules: refused when any fails. */
    public static RateInput check(String user, String grade, RateRequest request) throws InvalidRateException {
        String g = grade == null ? "" : grade.trim();
        if (!GRADES.contains(g)) {
            throw new InvalidRateException("The grade must be A, B or C.");
        }
        String rate = request.rate() == null ? "" : request.rate().trim();
        if (!rate.matches("\\d{1,5}(\\.\\d{1,2})?")) {
            throw new InvalidRateException("The rate must be a percent, 0.00 to 99999.99, with up to two decimals.");
        }
        String fromText = request.from() == null ? "" : request.from().trim();
        LocalDate from = null;
        if (!fromText.isEmpty()) {
            try {
                from = LocalDate.parse(fromText);
            } catch (DateTimeParseException e) {
                throw new InvalidRateException("The from-date must be a date, yyyy-mm-dd.");
            }
        }
        String toText = request.to() == null ? "" : request.to().trim();
        LocalDate to = null;
        if (!toText.isEmpty()) {
            try {
                to = LocalDate.parse(toText);
            } catch (DateTimeParseException e) {
                throw new InvalidRateException("The to-date must be a date, yyyy-mm-dd.");
            }
            if (from != null && to.isBefore(from)) {
                throw new InvalidRateException("The to-date must not be before the from-date.");
            }
        }
        return new RateInput(user, g, new BigDecimal(rate).setScale(2), from, to);
    }

    /** The RATE_SET line for the stored rate, set by the input's user. */
    public static void record(RateInput input, Rate rate, Audit audit) {
        audit.record("RATE_SET sheet=" + rate.sheetId() + " by=" + input.user()
                + " grade=" + rate.grade() + " rate=" + rate.pct().toPlainString()
                + (rate.from() != null ? " from=" + rate.from() : "")
                + (rate.to() != null ? " to=" + rate.to() : ""));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.claim.Tags;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a name is required, the grade
 *  is one of A, B or C, the grade's from-date (optional) a real yyyy-mm-dd date, the terms (optional)
 *  blank or a whole number of days, the terms' from-date (optional) a real yyyy-mm-dd date. Publishes the request with its name trimmed and its contact (optional)
 *  trimmed and lower-cased, and its tags (optional) normalised as a claim's are (see Tags.normalise). */
public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        body.set(check(request));
    }

    /** The request as the person form's rules leave it, or refused by them. */
    static PersonRequest check(PersonRequest request) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (name.length() > 200) {
            throw new InvalidPersonException("A name is at most 200 characters.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                LocalDate.parse(gradeFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date, yyyy-mm-dd.");
            }
        }
        String terms = request.terms() == null ? null : request.terms().trim();
        if (terms != null && !terms.isEmpty() && !terms.matches("\\d{1,4}")) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more, or blank for none.");
        }
        String termsFrom = request.termsFrom() == null ? "" : request.termsFrom().trim();
        if (!termsFrom.isEmpty()) {
            try {
                LocalDate.parse(termsFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The terms' from-date must be a date, yyyy-mm-dd.");
            }
        }
        String contact = request.contact() == null ? null : request.contact().trim().toLowerCase(Locale.ROOT);
        if (contact != null && contact.length() > 200) {
            throw new InvalidPersonException("A contact is at most 200 characters.");
        }
        String tags = request.tags() == null ? null : Tags.normalise(request.tags());
        if (tags != null && tags.length() > 1000) {
            throw new InvalidPersonException("Tags are at most 1000 characters.");
        }
        return new PersonRequest(request.user().trim(), name, grade, request.version(),
                gradeFrom.isEmpty() ? null : gradeFrom,
                terms == null || terms.isEmpty() ? terms : String.valueOf(Integer.parseInt(terms)), contact, tags,
                termsFrom.isEmpty() ? null : termsFrom);
    }
}
