import { SheetBody } from '../../slots/defs/sheet';
import { STATUSES, active as isActive, reviewLate, useClaims } from '../claims/claims';
import { GRADES, gradeOn, usePeople } from '../people/people';
import { periodDueTotal, usePeriods } from '../periods/periods';
import { diffDue, personDueTotal, sumDue, useRates } from '../rates/rates';
import { useFloor, useLate, useReviewSla } from '../settings/settings';
import { usePersonCap } from '../pools/pools';
import { useSheetToday } from '../sheet/sheet';
import { useVoidReasons } from '../voidreasons/voidreasons';

/** The sheet's summary, every figure as the list shows it: per grade the people on it today (those retired left
 *  out, whatever their retire date) and their due-totals added up (skipping n/a), per period its
 *  due-total and its change from the period before it by start date (none for the earliest), how many of them are active (see claims' active), and per status how many of the sheet's claims have it, and how many REVIEW claims are review-late (see reviewLate), and per void reason on the list how many VOID claims were
 *  voided with it. */
function Summary({ sheetId }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const periods = usePeriods(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const capOf = usePersonCap(sheetId);
  const reviewSla = useReviewSla(sheetId);
  const voidReasons = useVoidReasons(sheetId).data ?? [];
  const active = people.filter((p) => p.retiredFrom === null);
  const periodTotals = new Map(periods.map((p) => [p.name, periodDueTotal(p, claims, people, rates, floor, late)]));
  const byStart = [...periods].sort((a, b) => a.from.localeCompare(b.from));
  const periodChange = new Map(byStart.map((p, i) => [p.name, i === 0 ? ''
    : diffDue(periodTotals.get(p.name)!, periodTotals.get(byStart[i - 1].name)!)]));

  return (
    <section data-testid="summary">
      <h2>Summary</h2>
      <table>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = active.filter((p) => gradeOn(p, today) === g);
            return (
              <tr key={g} data-testid={`summary-grade-${g}`}>
                <th>Grade {g}</th>
                <td>
                  People <span data-testid={`summary-grade-${g}-count`}>{onGrade.length}</span>
                </td>
                <td>
                  Due total{' '}
                  <span data-testid={`summary-grade-${g}-due-total`}>
                    {sumDue(onGrade.map((p) => personDueTotal(p, claims, rates, today, floor, late, capOf(p.id), people)))}
                  </span>
                </td>
                <td>
                  Active{' '}
                  <span data-testid={`summary-grade-${g}-active`}>
                    {onGrade.filter((p) => isActive(p, claims, today)).length}
                  </span>
                </td>
              </tr>
            );
          })}
          {periods.map((p) => (
            <tr key={p.name} data-testid={`summary-period-${p.name}`}>
              <th>Period {p.name}</th>
              <td>
                Due total{' '}
                <span data-testid={`summary-period-${p.name}-due-total`}>
                  {periodTotals.get(p.name)}
                </span>
              </td>
              <td>
                Change <span data-testid={`summary-period-${p.name}-change`}>{periodChange.get(p.name)}</span>
              </td>
            </tr>
          ))}
          {STATUSES.map((s) => (
            <tr key={s} data-testid={`summary-status-${s}`}>
              <th>{s}</th>
              <td>
                Claims <span data-testid={`summary-status-${s}-count`}>{claims.filter((c) => c.status === s).length}</span>
              </td>
            </tr>
          ))}
          <tr data-testid="summary-review-late">
            <th>Review late</th>
            <td>
              Claims{' '}
              <span data-testid="summary-review-late-count">
                {claims.filter((c) => reviewLate(c, today, reviewSla)).length}
              </span>
            </td>
          </tr>
          {voidReasons.map((r) => (
            <tr key={r.id} data-testid={`summary-void-${r.reason}`}>
              <th>Voided: {r.reason}</th>
              <td>
                Claims <span data-testid={`summary-void-${r.reason}-count`}>{r.voided}</span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 23, Component: Summary });
import { useQueries } from '@tanstack/react-query';
import { useState } from 'react';
import { getJsonNow } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheet';
import { type Claim, useClaims } from '../claims/claims';
import { GRADES, gradeOn, type Person, usePeople } from '../people/people';
import { personDueTotal, sumDue, type Rate, useRates } from '../rates/rates';
import { usePersonCap } from '../pools/pools';
import { floorOf, lateOf, type Settings, useFloor, useLate } from '../settings/settings';
import { type Sheet, useSheetToday } from '../sheet/sheet';

/** Per grade the due-totals of a sheet's people on it today added up (retired ones left out), as its summary
 *  shows them. */
function gradeTotals(people: Person[], today: string, due: (p: Person) => string): Record<string, string> {
  const active = people.filter((p) => p.retiredFrom === null);
  return Object.fromEntries(GRADES.map((g) => [g,
    sumDue(active.filter((p) => gradeOn(p, today) === g).map(due))]));
}

/** Reads another sheet as the store holds it now, fresh at each compare: its per-grade summary due-totals, or
 *  null while they load, or 'missing' for a sheet that does not exist. */
function useOtherGrades(otherId: string, run: number): Record<string, string> | null | 'missing' {
  const base = `/api/sheets/${encodeURIComponent(otherId)}`;
  const parts = ['', '/people', '/claims', '/rates', '/settings'];
  const results = useQueries({
    queries: parts.map((part) => ({
      queryKey: ['sheet', otherId, 'compare', part, run],
      queryFn: () => getJsonNow<unknown>(`${base}${part}`),
      enabled: otherId !== '',
      retry: false,
      staleTime: Infinity,
      gcTime: 0,
    })),
  });
  if (otherId === '') return null;
  if (results[0].isError) return 'missing';
  if (results.some((r) => r.isPending)) return null;
  if (results.some((r) => r.isError)) return 'missing';
  const [sheet, people, claims, rates, settings] = results.map((r) => r.data) as
    [Sheet, Person[], Claim[], Rate[], Settings];
  const today = sheet.today;
  const floor = floorOf(settings);
  const late = lateOf(settings, today, claims, people);
  return gradeTotals(people, today,
    (p) => personDueTotal(p, claims, rates, today, floor, late, settings?.cap ?? '', people));
}

/** Compares this sheet with another, named by id: per grade of this sheet, <grade> <this sheet's summary
 *  due-total for it> <the other sheet's> (0.00 where the other has no one on it). No lines for a sheet that does
 *  not exist. */
function OtherSheetCompare({ sheetId }: { sheetId: string; user: string }) {
  const [entry, setEntry] = useState('');
  const [compared, setCompared] = useState({ id: '', run: 0 });
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const capOf = usePersonCap(sheetId);
  const other = useOtherGrades(compared.id, compared.run);
  const mine = gradeTotals(people, today,
    (p) => personDueTotal(p, claims, rates, today, floor, late, capOf(p.id), people));

  return (
    <section>
      <h3>Compare with another sheet</h3>
      <input data-testid="compare-sheet" value={entry} onChange={(e) => setEntry(e.target.value)} />
      <button type="button" data-testid="compare"
        onClick={() => setCompared((c) => ({ id: entry.trim(), run: c.run + 1 }))}>
        Compare
      </button>
      {other !== null && other !== 'missing' && (
        <ul>
          {GRADES.map((g) => (
            <li key={g} data-testid="compare-line" style={{ whiteSpace: 'pre' }}>
              {`${g} ${mine[g]} ${other[g]}`}
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 24.6, Component: OtherSheetCompare });

